export const reprocessarDocumento = async (idDocumento: string, options?: Parameters<typeof http>[1]): Promise<DocumentoOut> => {

  return http<DocumentoOut>(getReprocessarDocumentoUrl(idDocumento),
  {
    ...options,
    method: 'POST'


  }
);}





export const getReprocessarDocumentoMutationKey = () => ['reprocessarDocumento'] as const;

export const getReprocessarDocumentoMutationOptions = <TError = ErrorType<HTTPValidationError>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reprocessarDocumento>>, TError,ReprocessarDocumentoMutationVariables, TContext>, request?: SecondParameter<typeof http>}
): UseMutationOptions<Awaited<ReturnType<typeof reprocessarDocumento>>, TError,ReprocessarDocumentoMutationVariables, TContext> => {

const mutationKey = getReprocessarDocumentoMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof reprocessarDocumento>>, ReprocessarDocumentoMutationVariables> = (props) => {
          const {idDocumento} = props ?? {};

          return  reprocessarDocumento(idDocumento,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ReprocessarDocumentoMutationResult = NonNullable<Awaited<ReturnType<typeof reprocessarDocumento>>>

    export type ReprocessarDocumentoMutationError = ErrorType<HTTPValidationError>
    export type ReprocessarDocumentoMutationVariables = {idDocumento: string}

    /**
 * @summary Reprocessar Documento
 */
export const useReprocessarDocumento = <TError = ErrorType<HTTPValidationError>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reprocessarDocumento>>, TError,ReprocessarDocumentoMutationVariables, TContext>, request?: SecondParameter<typeof http>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof reprocessarDocumento>>,
        TError,
        ReprocessarDocumentoMutationVariables,
        TContext
      > => {
      return useMutation(getReprocessarDocumentoMutationOptions(options), queryClient);
    }
